using Astronomy.MediaFactory.Core.KnowledgeFoundation.Integration;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Integration;
public sealed class AstronomyKnowledgeFoundationCapabilityIdTests{[Fact]public void Validates_normalizes_and_compares(){var id=new AstronomyKnowledgeFoundationCapabilityId(AstronomyKnowledgeFoundationCapabilityKind.Catalog," catalog.metadata ");Assert.Equal("catalog.metadata",id.Value);Assert.Equal(id,new(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"catalog.metadata"));Assert.NotEqual(id,new(AstronomyKnowledgeFoundationCapabilityKind.QueryModel,"catalog.metadata"));Assert.NotEqual(id,new(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"Catalog.Metadata"));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeFoundationCapabilityId(AstronomyKnowledgeFoundationCapabilityKind.Catalog," "));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeFoundationCapabilityId((AstronomyKnowledgeFoundationCapabilityKind)99,"x"));}}
